  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('accepts list_sessions with optional limit and before cursor, dropping unknown fields', () => {
    const before = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'};
    const result = validateMessage({type: 'list_sessions', limit: 10, before, userId: 'u2'});

    expect(result).toEqual({
      valid: true,
      data: {type: 'list_sessions', limit: 10, before},
    });
  });

  it('accepts bare list_sessions without limit or before', () => {
    const result = validateMessage({type: 'list_sessions'});

    expect(result).toEqual({
      valid: true,
      data: {type: 'list_sessions'},
    });
  });

  it('rejects list_sessions when limit or before cursor is malformed', () => {
    expect(validateMessage({type: 'list_sessions', limit: 'ten'})).toEqual({
      valid: false,
      error: expect.stringContaining('limit'),
    });
    expect(validateMessage({type: 'list_sessions', limit: -1})).toEqual({
      valid: false,
      error: expect.stringContaining('limit'),
    });
    expect(validateMessage({type: 'list_sessions', limit: 1.5})).toEqual({
      valid: false,
      error: expect.stringContaining('limit'),
    });
    expect(validateMessage({type: 'list_sessions', before: 'not-an-object'})).toEqual({
      valid: false,
      error: expect.stringContaining('before'),
    });
    expect(
      validateMessage({
        type: 'list_sessions',
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''},
      })
    ).toEqual({
      valid: false,
      error: expect.stringContaining('sessionId'),
    });
    expect(
      validateMessage({
        type: 'list_sessions',
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)},
      })
    ).toEqual({
      valid: false,
      error: expect.stringContaining('sessionId'),
    });
    expect(
      validateMessage({
        type: 'list_sessions',
        before: {updatedAt: 'not-a-date', sessionId: 's1'},
      })
    ).toEqual({
      valid: false,
      error: expect.stringContaining('updatedAt'),
    });
    expect(
      validateMessage({
        type: 'list_sessions',
        before: {updatedAt: true, sessionId: 's1'},
      })
    ).toEqual({
      valid: false,
      error: expect.stringContaining('updatedAt'),
    });
  });
});

